MARK='''<svg viewBox="0 0 44 44" fill="none" aria-hidden="true"><path d="M8 9h28M8 22h28M8 35h28M9 8v28M22 8v28M35 8v28" stroke="currentColor" stroke-width="5"/><path d="M9 15v14M22 2v14M22 28v14M35 15v14" stroke="#b99a66" stroke-width="4"/></svg>'''
pages=[]
def card(title,text,kind='',badge=''):
 return f'<div class="card {kind}">{f"<span class=badge>{badge}</span>" if badge else ""}<h3>{title}</h3><p>{text}</p></div>'
def strip(text,kind=''):return f'<div class="strip {kind}">{text}</div>'
def steps(items):
 return '<div class="steps">'+''.join(f'<div class="step"><span class="num">{i}</span><div><h3>{a}</h3><p>{b}</p></div></div>'for i,(a,b)in enumerate(items,1))+'</div>'
def shot(name,caption,cls=''):
 return f'<figure class="shot {cls}"><img src="assets/{name}.png" alt="{escape(caption)}"><figcaption>{caption}</figcaption></figure>'
def table(headers,rows,cls=''):
 return '<table class="table '+cls+'"><thead><tr>'+''.join('<th>'+c+'</th>'for c in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>'for c in r)+'</tr>'for r in rows)+'</tbody></table>'
def add(kicker,title,intro,body,cls=''):
 n=len(pages)+1
 pages.append(f'<section class="page {cls}" id="page-{n}"><div class="running"><div class="brand">{MARK} MARS TEXTILE</div><span>Godown Ledger · Office handbook</span></div><div class="content"><p class="kicker">{kicker}</p><h1>{title}</h1><p class="intro">{intro}</p>{body}</div><div class="footer"><span>Mars Textile · Client training · 21 October 2026</span><span class="version">Working release guide</span><b>{n:02d}</b></div></section>')
add('The office book','From the mill<br>to your money.','A visual guide to receiving cloth, making bills, collecting udhar and closing the office day.',
'''<div class="cover-grid"><div><span>01 / GOODS</span><strong>Mills & godown</strong><span>Every product, lot and quantity</span></div><div><span>02 / MONEY</span><strong>Bills & recovery</strong><span>Every buyer and outstanding rupee</span></div><div><span>03 / CONTROL</span><strong>Books & evening note</strong><span>One shared office record</span></div></div><div class="space"></div><div class="grid2"><div class="toc"><p class="subheading">Learn the daily process</p><a href="#page-2">Follow the whole system <b>02</b></a><a href="#page-3">Know each person’s desk <b>03</b></a><a href="#page-7">Receive → price → sell → recover <b>07–12</b></a><a href="#page-16">Prepare and share the evening report <b>16</b></a></div><div class="toc"><p class="subheading">Keep for office reference</p><a href="#page-5">Find every main screen <b>05</b></a><a href="#page-13">Returns and direct deals <b>13–14</b></a><a href="#page-17">Reports and owner controls <b>17–18</b></a><a href="#page-19">Worked example and daily checklist <b>19–20</b></a></div></div>'''+strip('<b>One shared book. A personal desk for each person.</b><br>Use the office website in a browser. No software installation is needed on staff computers.')+'<p class="print-note">Screens use demonstration data from the working application. Example names and figures are for training, not the client’s live accounts. Keep the separate one-page desk card beside each computer.</p>', 'cover')
add('01 / The whole system','Cloth goes out.<br>Money comes back.','Each posted transaction updates the shared book. Staff do their part once; the owner sees the connected result.',
'''<p class="subheading">Normal godown trade · physical goods</p><div class="flow"><div class="node"><span class="label">Supplier</span><h3>Mill</h3><p class="small">Purchase and cloth receipt</p></div><span class="arrow">→</span><div class="node dark"><span class="label" style="color:#d8e7dc">Your office</span><h3>Godown</h3><p class="small">Price the lot, then make it available</p></div><span class="arrow">→</span><div class="node"><span class="label">Customer</span><h3>Buyer</h3><p class="small">Cash bill or udhar sale</p></div></div><div class="space"></div><p class="subheading">The matching money trail</p><div class="grid2">'''+card('Recovery from buyers','A receipt reduces what the buyer owes. Record the payment method and reference.','pale')+card('Payments to mills','A payment reduces the mill balance. Track cheques in the PDC register.','pale')+'''</div><div class="space"></div><div class="flow"><div class="node"><h3>Transactions</h3><p class="small">Purchases · sales · receipts · payments · returns</p></div><span class="arrow">→</span><div class="node dark"><h3>Books & reports</h3><p class="small">Ledger · balances · stock · evening note</p></div></div>'''+strip('<b>Direct deal:</b> mill → buyer, without entering the godown. Record it through <b>Direct deals</b>, so the buyer and mill accounts are still updated. See page 14.')+strip('<b>Posting is the point of change.</b> A receipt waiting for a rate is not yet saleable stock. A typed form or unsent draft is not proof that a bill has posted.','gold'))
add('02 / People & trust','Four people.<br>Four different desks.','The office shares one mill login. Each person’s own PIN opens the work appropriate to that person.',
'<div class="grid2">'+card('Godown keeper','<b>Does:</b> add mills, receive unpriced cloth, view physical lots and stock movement history.<br><br><b>Does not see:</b> prices, buyer dues or books. Report count differences to the owner.','','GODOWN')+card('Salesman','<b>Does:</b> create sales bills, maintain buyers and record recovery.<br><br><b>Does not see:</b> purchase costs, full books or the complete evening workbook.','','SALES')+card('Bookkeeper','<b>Does:</b> price cloth, record purchases, payments, returns and direct deals; review accounts and reports.<br><br><b>Does not manage:</b> staff PINs, company settings or full backup recovery.','','BOOKS')+card('Owner','<b>Does:</b> see all work, manage people and PINs, change settings, approve stock corrections and keep backups.<br><br><b>Keep the owner PIN private.</b> Whoever knows it can open the owner’s desk.','green','OWNER')+'</div>'+strip('<b>Stock corrections:</b> the keeper reports the difference; the owner makes the authorised Stock adjustment. Do not enter a second sale or receipt just to force the quantity to match.')+'<div class="space"></div>'+table(['When someone leaves a computer','When someone leaves the business'],[['Press <b>Leave the desk</b>. The next person opens their own work.','The owner disables that person under <b>More → People and pins</b>.']]))
add('03 / Open your desk','Sign in as the mill.<br>Work as yourself.','Bookmark the office HTTPS website on every computer or phone. Internet access is required.',
'<div class="two-shot">'+shot('login','1 · Shared mill sign-in. Enter the office email and password.')+shot('pin','2 · Personal desk. Select your name and enter your own 4-digit PIN.')+'</div><div class="space-sm"></div>'+steps([('Open the office website','Use the shared mill email and password supplied by the owner.'),('Choose your name and enter your PIN','A wrong PIN does not open the desk. Five wrong attempts lock that person’s PIN for 15 minutes; ask the owner for help.'),('Press Leave the desk when finished','The next person uses their own PIN. Keep the owner’s PIN and all passwords private.')])+strip('<b>Other office computers stay connected to the same book.</b> Read screens refresh about every five seconds while visible and online. Refresh pauses while you are typing, to preserve the unfinished entry.'))
add('04 / Find your work','The six office sections.','Use these menu names in the working release. A person sees only the sections allowed for their desk.',
'<div class="grid2 cards-small">'+''.join('<div class="card map-card"><span class="badge">'+str(i).zfill(2)+'</span><h3>'+title+'</h3><ul class="map-list">'+''.join('<li>'+x+'</li>'for x in items)+'</ul></div>'for i,(title,items)in enumerate([
('Day book',['Overview','Alerts']),('Godown & mills',['Godown stock · Mills','Cloth products & lots · Price received cloth','Reorder sheet · Stock adjustment (owner)']),('Bills & recovery',['Sales bills · Recovery · Buyers','Direct deals · Buyer returns','Quotations · Routes (where permitted)']),('Books & accounts',['Accounts & ledger · Bank accounts','PDC cheques · Purchases','Mill accounts · Mill pay schedule · Expenses']),('Evening & reports',['Evening note · All reports','Profit & loss · Balance sheet','Sales targets']),('More',['People and pins (owner)','Settings & office file (owner)','Office guide'])],1))+'</div>'+strip('<b>Two mill screens have different purposes.</b> <b>Mills</b> is a physical supplier directory the keeper can use. <b>Mill accounts</b> contains the financial balances and payments for the owner/bookkeeper.')+strip('<b>The cloud release needs Internet.</b> Offline billing is not available. If the connection fails, reconnect and check the bill list before entering the bill again.','gold'))
add('05 / Before the first real day','Start with agreed figures.','The old manual books do not appear automatically. Choose a start date and approve opening balances before relying on the totals.',
'<div class="grid2">'+card('Cloth products','Add the product name, quality/count, unit, mill and default rates. Use a consistent description the keeper and salesman recognise.','','01')+card('Mills & buyers','Create each party once. Check spelling, contact details and area. Avoid duplicate names for the same business.','','02')+card('Opening stock','Agree each product, lot, remaining quantity and original cost. Match the software total to the physical godown count.','','03')+card('Opening money & dues','Approve cash/bank, buyer receivables and mill payables with the bookkeeper. Do not guess old balances.','','04')+'</div><div class="space"></div><div class="screen-key"><h3>Keep each product in its own unit.</h3><p class="small">KG, metres and thaan are separate measures. Quantities allow up to three decimal places, for example 12.500 KG. A thaan is not automatically converted into metres.</p></div>'+strip('<b>Who checks this?</b> Owner + bookkeeper approve the start date and figures. The keeper confirms physical lots; the salesman confirms buyer details.')+'<div class="space"></div><h3>A useful opening list</h3>'+table(['Stock list','Buyer list','Mill list'],[['Product · lot · unit<br>Quantity · cost','Name · opening due<br>Known bill/due dates','Name · opening payable<br>Cheque commitments']]))
add('06 / Keeper · cloth comes in','Receive the cloth.<br>Leave the rates to the bookkeeper.','A physical receipt starts the process. It does not make the cloth available for sale until it has been priced and posted.',
'<div class="path">Godown & mills → Godown stock → Cloth received</div>'+shot('receive-cloth','Actual keeper form · sample values entered for training; this example was not submitted.','tall')+steps([('Select the mill and cloth product','The owner/bookkeeper adds cloth products first. The keeper can add a missing mill under Mills.'),('Enter the lot and measured quantity','Copy the lot/thaan number from the delivery slip. Confirm the product’s unit and add shade, quality or rack notes.'),('Choose Record cloth for pricing','Check the saved confirmation. The receipt goes to Waiting for a rate for the bookkeeper.')])+strip('<b>Do not receive the same delivery twice.</b> Check the waiting list if the screen or connection interrupted the confirmation.','gold'))
add('07 / Bookkeeper · approve the lot','A rate turns a receipt<br>into saleable stock.','Use the mill’s bill to check the cost and quantity before posting. The keeper’s physical receipt and the priced purchase belong to the same delivery.',
'<div class="path">Godown & mills → Price received cloth</div><div class="flow"><div class="node"><span class="label">Before</span><h3>Waiting for a rate</h3><p class="small">Mill · cloth · lot · quantity<br>Not yet available to sell</p></div><span class="arrow">→</span><div class="node dark"><span class="label" style="color:#d2e5d7">After posting</span><h3>Available lot</h3><p class="small">Cost recorded · mill payable updated<br>Lot can be selected for a bill</p></div></div><div class="space"></div><div class="grid2"><div class="card"><span class="label">Purchase rate per KG</span><div class="field">Rs 100.00</div><p class="small" style="margin-top:12px">12.500 KG received → Rs 1,250.00 cost</p></div><div class="card"><span class="label">Selling rate per KG</span><div class="field">Rs 150.00</div><p class="small" style="margin-top:12px">Default selling rate for this training example</p></div></div><div class="space"></div>'+steps([('Review the pending receipt','Check the mill, product, lot and quantity against the delivery and mill bill.'),('Add purchase and selling rates','Choose Price and post receipt only when the figures are correct.'),('Confirm the stock and mill account','The lot becomes available; the purchase is recorded in the books.')])+strip('<b>Alternative: enter a full priced purchase.</b> Use <b>Books & accounts → Purchases</b> when you already have the rates. Do not also post the same delivery from the pending receipt list.')+strip('<b>Cash / credit / PDC:</b> a purchase can record cash paid or leave the balance owing. Record a post-dated mill cheque separately in the PDC register; do not count it as a second purchase.','gold'))
add('08 / Godown · follow the quantity','Stock goes out automatically<br>when a sales bill posts.','There is no second dispatch entry for the keeper. Posted purchases, sales, returns and authorised adjustments build the movement history.',
'<div class="path">Godown & mills → Godown stock → Stock movement history</div>'+shot('movement-history','Actual quantity-only keeper history · demonstration purchase, sale and buyer return.','compact')+'<div class="grid3">'+card('12.500 KG','Received and priced.','pale')+card('− 2.750 KG','Deducted by a posted sales bill.','pale')+card('+ 0.500 KG','Added back by a buyer return.','pale')+'</div><div class="space"></div><div class="card green"><div class="row" style="justify-content:space-between"><div><span class="label" style="color:#d2e5d7">Remaining quantity</span><p class="small">Each lot keeps its product’s unit.</p></div><strong class="big">10.250 KG</strong></div></div>'+strip('<b>The keeper sees quantities, not money.</b> Use the document reference and lot to explain a movement. The owner/bookkeeper reviews stock valuation separately.')+strip('<b>Count does not match?</b> Check pending receipts and recent bills/returns, recount the lot and report the difference. Only the owner posts a stock adjustment.','gold'))
add('09 / Salesman · make the bill','Sell the right lot<br>to the right buyer.','The bill updates the buyer’s account and deducts the physical quantity from the selected available lot.',
'<div class="path">Bills & recovery → Sales bills → New Invoice</div>'+shot('sales-entry','Actual bill-entry detail · lot, quantity, selling rate and credit terms. Review the full bill before choosing Create Invoice.','compact')+steps([('Choose the buyer and cloth product','For udhar, use a registered buyer. Check the chosen lot, unit and quantity.'),('Check the selling rate and payment terms','Review discount/tax if applicable. A walk-in bill must be fully paid; a registered buyer can have a credit balance.'),('Post once, then verify the saved bill','Choose Create Invoice. Check its number and totals, then print or save the bill using its Print option.')])+'<div class="space-sm"></div><div class="grid2">'+card('Cash / fully paid','The bill and receipt record the sale and the money received.','pale')+card('Udhar / on account','The unpaid amount becomes the buyer’s outstanding balance.','pale')+'</div>'+strip('<b>An open form does not reserve stock.</b> Another desk may sell first. If stock is no longer available, review the lot; do not force a duplicate bill.','gold'))
add('10 / Recovery · collect the udhar','Who owes us?<br>What is overdue?','Recovery starts with the buyer’s balance. Aging helps decide whom to follow up first.',
'<div class="path">Bills & recovery → Recovery · Buyers → buyer ledger → Record Payment</div>'+shot('recovery','Actual recovery list · sample buyer balance after a sale, general receipt and return.','compact')+steps([('Open the buyer and check the balance','Review bills, returns and previous receipts before collecting.'),('Record what was actually received','Enter the amount, payment method and reference. Record any authorised discount separately; do not enter it as cash.'),('Confirm the new balance','The buyer ledger, Recovery and Aging should agree. Use the document reference when following up.')])+strip('<b>How the list is prioritised:</b> oldest outstanding due date first, then amount. If a bill has no due date, aging uses the bill date. General credits are applied to the oldest open amount for aging.')+'<div class="space-sm"></div><div class="pill-row">'+''.join('<span class="pill">'+x+'</span>'for x in ['Current / 0–30 days','31–60 days','61–90 days','90+ days','Opening / undated'])+'</div><p class="print-note">Undated opening balances are shown separately. The software does not invent old invoice dates.</p>')
add('11 / Bookkeeper · pay the mills','A purchase is not<br>the same as a payment.','Record buying once. Then record how the mill is paid, whether immediately or later.',
'<div class="path">Books & accounts → Mill accounts · Mill pay schedule · PDC cheques</div>'+table(['Action','What the office records','What to check'],[['Buy on credit','Purchase / priced receipt','Mill payable rises; stock is recorded.'],['Pay the mill','Payment on the mill account','Amount, method, date and reference.'],['Plan a due payment','Mill pay schedule','A plan is not proof that payment was posted.'],['Issue / receive a future cheque','PDC register','Party, number, bank, due date and amount.']])+'<div class="space"></div><h2>Follow the cheque through its real status.</h2><div class="flow"><div class="node"><span class="badge">PENDING</span><h3>Recorded</h3><p class="small">The cheque is tracked in a clearing account, not as available cash.</p></div><span class="arrow">→</span><div class="node dark"><span class="badge">DEPOSITED</span><h3>Presented / deposited</h3><p class="small">Update the register when the bank event is confirmed.</p></div></div><div class="card gold"><h3>If it bounces</h3><p>Mark it <b>Bounced</b> with a reason. The related receipt/payment is reversed and the buyer due or mill payable is reinstated.</p></div>'+strip('<b>Avoid double counting.</b> Creating the PDC already creates its linked cheque receipt/payment. Do not enter that same cheque again as a separate payment.')+'<p class="print-note">Bookkeeper/owner manages the cheque register. Keep bank confirmation and cheque details with the office records.</p>')
add('12 / Exceptions · returns','Start the return<br>from the original document.','Returns use the original document’s remaining returnable quantity and values, so stock and party balances stay connected.',
'<div class="grid2">'+card('Buyer returns cloth','Open the original sales bill → <b>Return</b>.<br><br>Select the original product/lot and the quantity actually returned. The return credits the buyer and adds stock back. A walk-in return can refund cash.','','BUYER RETURN')+card('Cloth goes back to the mill','Open the original purchase → <b>Return</b>.<br><br>Select the original line and quantity sent back. It reduces godown stock and the amount owed to the mill.','','MILL RETURN')+'</div><div class="space"></div><h2>A simple buyer-return example</h2><div class="flow"><div class="node"><span class="label">Original sale</span><h3>2.750 KG</h3><p class="small">At Rs 150 per KG<br>Bill: Rs 412.50</p></div><span class="arrow">→</span><div class="node dark"><span class="label" style="color:#d2e5d7">Returned</span><h3>0.500 KG</h3><p class="small">Credit: Rs 75.00<br>Stock restored: 0.500 KG</p></div></div>'+steps([('Check the original number','The quantity must belong to that bill/purchase and must not already have been returned.'),('Check the saved return','Confirm its reference, quantity and credit. Review the original document and updated party ledger.')])+strip('<b>Who handles returns?</b> Owner or bookkeeper. The keeper can confirm the physical quantity; the salesman should refer the request to the authorised person.')+strip('<b>Corrections are different from returns.</b> For a wrong posting, ask the owner/bookkeeper to use the permitted correction or reversal with a reason. Do not hide it with an invented payment or stock entry.','gold'))
add('13 / Direct deals','Mill straight to buyer.<br>No godown movement.','Use a direct deal only when the goods never enter your godown. The purchase and sale are still recorded in the shared books.',
'<div class="path">Bills & recovery → Direct deals</div><div class="flow"><div class="node"><span class="label">From</span><h3>Mill</h3><p class="small">Cost and mill payment terms</p></div><span class="arrow">→</span><div class="node dark"><span class="label" style="color:#d2e5d7">Direct delivery</span><h3>Buyer</h3><p class="small">Selling rate and buyer payment terms</p></div></div><div class="card gold"><h3>Godown stock stays unchanged.</h3><p>Do not receive these goods into stock and do not make a second ordinary stock sale for the same direct deal.</p></div><div class="space"></div>'+steps([('Owner/bookkeeper enters the deal','Choose the mill and buyer. Enter cloth/lot description, quantity, unit, mill cost and selling rate.'),('Choose both payment terms','The buyer can pay cash now or on account. The mill can be paid cash now or left on account.'),('Post and follow the linked records','The sales side appears in sales and recovery. The purchase side updates the mill account and trading cost.')])+strip('<b>Example:</b> direct cost Rs 10,000 and direct sale Rs 12,000 give Rs 2,000 trading margin before other expenses. Stock remains unchanged.')+strip('<b>To reverse a direct deal:</b> owner/bookkeeper reverses linked payments first, then uses <b>Reverse direct deal</b> with a reason. There is no godown stock return for a deal that never entered stock.','gold'))
add('14 / Books & accounts','One transaction.<br>Its matching effect in the books.','Posting creates the financial entries behind the scenes. The bookkeeper reviews the resulting balances and investigates differences.',
'<div class="grid2">'+card('Accounts & ledger','Review the account list and each account’s movements. Use the relevant cash receipt/payment or voucher for the actual transaction.','','BOOKS')+card('Bank accounts','Review bank balances and match movements with the statement. Do not treat a pending cheque as cash in hand.','','BANK')+card('Expenses','Record office expenses with the right category, date, amount and payment method. Keep the supporting slip.','','COSTS')+card('Opening balances & journals','The owner/bookkeeper records approved opening figures and justified accounting corrections. Keep a clear reason and document trail.','','CONTROL')+'</div><div class="space"></div><h2>Three checks at closing</h2>'+table(['Report','Question it answers'],[['Trial balance','Do total debits and credits agree?'],['Profit & loss','What is the trading result after cost of sales and expenses?'],['Balance sheet','What do we own, what do we owe, and what is the equity?']])+strip('<b>Profit is not the same as cash.</b> An udhar sale can earn margin while the money is still outstanding. Recovery brings in money but is not a second sale.')+strip('<b>Balanced entries are only one check.</b> Also compare physical stock, buyer/mill balances, cash, bank and supporting documents. Investigate a stock/books warning before signing off the day.','gold'))
add('15 / Evening close & WhatsApp','Prepare the day.<br>Share the Excel file.','The owner or bookkeeper reviews the evening note and prepares the workbook from the shared office book.',
'<div class="path">Evening & reports → Evening note</div>'+shot('excel-share','Actual desktop sharing controls · prepare the workbook, then download or use a supported phone share menu.','compact')+'<div class="grid2">'+card('On a supported phone','<b>Prepare Excel for WhatsApp</b><br>→ <b>Share Excel file</b><br>→ choose WhatsApp and recipient<br>→ confirm the attachment and send.','pale')+card('On a laptop / PC','<b>Prepare Excel for WhatsApp</b><br>→ <b>Download prepared Excel</b><br>→ WhatsApp: <b>Attach → Document</b><br>→ select the file and send.','pale')+'</div>'+strip('<b>Check before sharing:</b> purchases, sales, returns, recovery, mill payments and any stock/books warning. The workbook is a snapshot; prepare a fresh copy if more entries are posted.')+strip('<b>Manual sharing requires you to press Send.</b> “Email the note” opens a text draft; attach the downloaded workbook yourself. Automatic nightly delivery needs separately configured and verified providers and scheduling.','gold')+'<p class="print-note">Dates use Pakistan time. Daily activity covers the business day; stock, buyer dues and account balances are current when the workbook is prepared.</p>')
add('16 / Reports & decisions','Choose a report<br>for the question you have.','The report menu is a set of office tools. Access depends on the person’s desk; the full financial reports are for the owner/bookkeeper.',
'<div class="path">Evening & reports → All reports</div>'+table(['Office question','Reports / screens to use'],[['What sold and at what margin?','Sales Report · Sales Detail · Monthly Sales Statement (customer-wise)'],['What was bought and what remains?','Purchase Report · Stock Valuation · Reorder sheet'],['Who owes us, and since when?','Customer Recovery · Aging · Area-wise Report'],['Who collected the money?','Collection Report · Salesman Performance · Monthly Cash Receiving (product-wise)'],['Are we meeting the plan?','Sales Targets · Area-wise Report'],['Do the books tie and are we profitable?','Trial Balance · Profit & Loss · Balance Sheet · Accounts ledger'],['What about cheques and expenses?','PDC Register · Expense Summary'],['What happened today?','Evening note · Activity Audit Log (owner)'],['What are our recorded tax totals?','FBR Tax Summary — a summary of entered tax, not electronic filing or an FBR e-invoice.']],'tight')+'<div class="space"></div><h3>The evening workbook has 11 tabs.</h3><div class="pill-row">'+''.join('<span class="pill">'+x+'</span>'for x in ['Summary','Purchases','Sales','Recovery','Mill Payments','Stock','Returns','Waiting for Rate','Buyer Dues','Accounts','Evening Note'])+'</div><div class="space"></div><div class="grid2">'+card('Other office tools','Quotations prepare an offer; they are not a posted sales bill. Routes help organise visits; Alerts and Reorder sheet flag stock follow-up.','','WHEN PERMITTED')+card('Read the filters','Check dates, buyer/mill, payment status and other filters before printing or exporting. Different periods produce different totals.','','BEFORE COMPARING')+'</div>')
add('17 / Owner controls','People, office details<br>and a recoverable book.','The owner controls the staff list, company settings and full encrypted backups. These tasks are separate from ordinary stock and sales entry.',
'<div class="path">More → People and pins · Settings & office file</div>'+steps([('Add each person with the right role','Use People and pins. Give each person a different 4-digit PIN. Reset or disable access when required; keep the owner PIN private.'),('Check the office profile','Under Settings & office file, check company name, address, contact details and the information printed on office documents.'),('Download an encrypted office backup','Use Download encrypted office backup. Keep copies in the agreed safe location, with the recovery key stored separately.'),('Confirm recovery with your support person','A backup validation checks the file; it does not overwrite the live book. A restore is handled by support using a separate empty database.')])+'<div class="space"></div><div class="grid2">'+card('Excel report','For reading, sharing and office analysis.<br><br><b>It is not a full recovery backup.</b>','pale')+card('Encrypted office backup','For recovering the company book with the correct key and a verified recovery process.<br><br><b>Keep it separately from the key.</b>','green')+'</div>'+strip('<b>Agree the backup routine.</b> Confirm the destination, frequency and responsible person. Do not assume an offsite or nightly backup is active until it has been configured and checked.','gold')+'<p class="print-note">Never put passwords, PINs, database addresses, recovery keys or decrypted backups into a staff WhatsApp group.</p>')
add('18 / A complete worked example','Follow one lot<br>through the whole day.','Training example: no tax, discount, opening balances or mill payment. All amounts below relate to this one lot and buyer.',
 table(['Step','What happens','Quantity / amount'],[['1 · Price the receipt','12.500 KG at Rs 100 per KG','Stock cost <b>Rs 1,250.00</b><br>Mill payable <b>Rs 1,250.00</b>'],['2 · Sell on udhar','2.750 KG at Rs 150 per KG','Bill <b>Rs 412.50</b><br>Stock left <b>9.750 KG</b>'],['3 · Collect recovery','Receive Rs 100 from the buyer','Buyer due <b>Rs 312.50</b>'],['4 · Buyer returns cloth','Return 0.500 KG from the original bill','Credit <b>Rs 75.00</b><br>Stock left <b>10.250 KG</b>']])+'<div class="space"></div><div class="grid3">'+card('Rs 237.50','Buyer still owes<br><span class="small">412.50 − 100.00 − 75.00</span>','pale')+card('10.250 KG','Physical stock left<br><span class="small">12.500 − 2.750 + 0.500</span>','pale')+card('Rs 1,025.00','Stock at cost<br><span class="small">10.250 × 100.00</span>','pale')+'</div><div class="space"></div><div class="card green"><h3>Check the same result in more than one place.</h3><p>Buyer ledger, Recovery and Aging: <b>Rs 237.50</b> due.<br>Godown and stock valuation: <b>10.250 KG</b> at <b>Rs 1,025.00</b> cost.<br>Mill account: <b>Rs 1,250.00</b> payable until it is paid.</p></div>'+strip('<b>Trading result:</b> net sales after the return are Rs 337.50. Net cost of goods sold is Rs 225.00, so gross margin is Rs 112.50 before office expenses. Only Rs 100.00 has been collected in this example.')+'<p class="print-note">Use a separate training book for practice. Do not post invented demonstrations into the client’s live accounts.</p>')
add('19 / Daily routine & support','Open cleanly.<br>Close with confidence.','Keep the separate one-page desk card at each computer. Use this page when training a new member of staff.',
'<div class="grid2"><div class="card"><h3>At the start</h3>'+''.join('<div class="check">'+x+'</div>'for x in ['Open the website; choose your own PIN.','Check pending cloth and due recovery.','Review the day’s mill payments/cheques.'])+'</div><div class="card"><h3>Before leaving</h3>'+''.join('<div class="check">'+x+'</div>'for x in ['Confirm saved bills, receipts and returns.','Bookkeeper reviews cash, bank and books.','Owner/bookkeeper shares the evening file.','Owner confirms the backup; leave the desk.'])+'</div></div><div class="space"></div>'+table(['If this happens…','Do this'],[['Internet fails / saving is uncertain','Reconnect. Check the relevant bill/receipt list and document number before retrying. Offline posting is unavailable.'],['PIN fails or access says Forbidden','Check the selected person. Ask the owner about the PIN or role; do not use the owner PIN as a workaround.'],['Stock or a buyer balance seems wrong','Check pending receipts, original bills, payments and returns. Record the reference and ask the bookkeeper/owner.'],['A report or share button is unavailable','Check your role. Full evening Excel is owner/bookkeeper only; desktop WhatsApp needs a downloaded document.']],'tight')+'<div class="space"></div><div class="card pale"><h3>For support, send four useful details.</h3><p><b>Screen name · document number · Pakistan time · exact error text.</b><br>A screenshot helps; exclude passwords, PINs and private recovery keys.</p></div><p class="print-note">Training order: sign-in → keeper receipt → bookkeeper pricing → sale → recovery → return/direct deal → evening Excel → owner controls. Confirm the real office website, support contact and backup routine during handover. FBR e-invoicing, job-work, multi-godown transfers and automatic delivery activation require separate agreement/setup.</p>')
html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mars Textile — Visual Office Handbook</title><style>'+CSS+'</style></head><body>'+''.join(pages)+'</body></html>'
(ROOT/'MARS-TEXTILE-VISUAL-HANDBOOK.html').write_text(html)
# Separate compact printable one-page desk card, matching the handbook.
quick='''<div class="grid2">'''+card('Start your desk','Office website → shared mill login → choose your name → your 4-digit PIN. Press <b>Leave the desk</b> when finished.','green')+card('Keep one shared book','Internet is required. If saving is uncertain, check the document list before entering the transaction again.','pale')+'''</div><div class="space"></div>'''+table(['Who','Do this','Then check'],[['Keeper','Godown stock → receive cloth','Correct mill, product, lot and quantity.<br>Waiting for a rate = not saleable yet.'],['Bookkeeper','Price received cloth → post','Cost/selling rates checked.<br>Available lot and mill payable updated.'],['Salesman','Sales bills → New Invoice','Correct buyer, lot, quantity and terms.<br>Posted bill deducts stock automatically.'],['Salesman / bookkeeper','Buyer ledger → Record Payment','Amount, method and reference.<br>Buyer balance reduced once.'],['Bookkeeper','Mill accounts / PDC cheques','Record payments separately from buying.<br>Do not record a cheque twice.'],['Owner / bookkeeper','Returns from original document','Only the unreturned quantity.<br>Direct deal reversal is separate.'],['Owner / bookkeeper','Evening note → prepare Excel','Review stock/books checks.<br>Prepare a fresh copy after late entries.'],['Owner','Settings → encrypted backup','Safe destination and separate key.<br>Excel is not a full recovery backup.']],'tight')+'''<div class="space"></div><div class="grid2">'''+card('Share Excel on a phone','Prepare Excel → Share Excel file → WhatsApp → recipient → Send. If unsupported, download and attach the file.','pale')+card('Share Excel on a PC','Prepare Excel → Download prepared Excel → WhatsApp → <b>Attach → Document</b> → choose the file → Send.','pale')+'''</div>'''+strip('<b>No second dispatch entry.</b> Sales bills deduct stock. The keeper reports count differences; the owner posts authorised adjustments. Direct deals never enter godown stock.')+'''<p class="print-note"><b>Help:</b> send screen name, document number, Pakistan time and error text to your support person. Keep passwords/PINs private. Automatic nightly delivery is separate setup.</p>'''
q='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Mars Textile — Daily Desk Card</title><style>'+CSS+'''.page{padding-top:30px}.running{margin-bottom:14px}h1{font-size:30px}.intro{margin-bottom:17px}.card{padding:14px}.table{font-size:11px}.table.tight td{padding:8px 10px}.strip{font-size:11px}.space{height:14px}</style></head><body><section class="page"><div class="running"><div class="brand">'''+MARK+''' MARS TEXTILE</div><span>Keep beside the office computer</span></div><p class="kicker">Daily desk card</p><h1>One day. One shared book.</h1><p class="intro">Receive → price → sell → recover → reconcile → share → leave the desk.</p>'''+quick+'''<div class="footer"><span>Mars Textile · Godown Ledger</span><span>21 October 2026 · Keep the full handbook for detail</span><b>01</b></div></section></body></html>'''
(ROOT/'MARS-TEXTILE-DAILY-DESK-CARD.html').write_text(q)
print('Created',len(pages),'handbook pages and one desk card.')
